package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class TaskProfessionalPackageAuthoringSchemaTest {
 final PermissionSchema json=new PermissionSchema();final TaskProfessionalPackageAuthoringSchema schema=new TaskProfessionalPackageAuthoringSchema(json);
 TaskProfessionalPackageAuthoringSchemaTest()throws Exception{}
 static String id(int n){return String.format("00000000-0000-4000-8000-%012d",n);}static final String H="a".repeat(64);
 ObjectNode request(String kind){var n=json.object().put("schema_version","1.0.0").put("kind",kind).put("preparation_sha256",H);n.putArray("content_sources");var p=json.object().put("schema_version","1.0.0").put("node_kind","N02");switch(kind){case "PROMPT"->p.put("system_instructions","Use only verified sources. 医疗 😀").put("input_encoding","TASK_NODE_INPUT_CANONICAL_JSON");case "PROFILE"->{p.put("profile_name","medical-agent").put("projection","TEXT_SYSTEM_USER_V1").put("system_prefix","");p.putArray("files").add(json.object().put("relative","profiles/medical.json").put("sha256",H).put("size_bytes","8"));p.set("adapter_artifact",artifact());}case "ROLE"->{p.put("role_name","Researcher");p.set("prompt_basis",json.tree(new PermissionProtocol.Basis(id(3),H)));p.set("profile_artifact",artifact());}}n.set("package",p);return n;}
 ObjectNode artifact(){return json.object().put("artifact_id",id(4)).put("sha256",H).put("size_bytes","8").put("media_type","application/json");}
 @Test void acceptsOnlyThreeFrozenPublishedPackageKinds()throws Exception{for(String kind:List.of("PROMPT","PROFILE","ROLE")){var request=request(kind);schema.validateRequest(request);assertEquals(request,schema.request(schema.bytes(request)));assertEquals("f4510bb51711d57e11aa0fb5405249ecc8e51437a21cafb644f89d7da690069e",schema.descriptor(kind).required("schema_sha256").textValue());}}
 @Test void rejectsUnknownFieldsKindsAndCallerSuppliedAuthority()throws Exception{for(String kind:List.of("PROMPT","PROFILE","ROLE")){var request=request(kind);for(String field:List.of("approved","tenant_id","object_key","object_version","artifact_id","production_eligible","credentials","permission")){var bad=request.deepCopy().put(field,"caller");assertThrows(SchemaRejection.class,()->schema.validateRequest(bad));}for(String field:List.of("schema_version","kind","package","content_sources","preparation_sha256")){var bad=request.deepCopy();bad.remove(field);assertThrows(SchemaRejection.class,()->schema.validateRequest(bad));}}assertThrows(SchemaRejection.class,()->schema.validateRequest(request("PROMPT").put("kind","TOOL")));}
 @Test void rejectsTraversalAmbiguousPathsDuplicateFilesAndByteOverflow()throws Exception{for(String path:List.of("profiles/../x","profiles//x","profiles/./x","profiles/a/","profiles/a%2fb","profiles/a\\b","profiles/\u0085bad")){var bad=request("PROFILE");((ObjectNode)bad.at("/package/files/0")).put("relative",path);assertThrows(SchemaRejection.class,()->schema.validateRequest(bad),path);}assertTrue(TaskProfessionalPackageAuthoringSchema.safeProfilePath("profiles/my..valid.json"));var duplicate=request("PROFILE");duplicate.withObject("package").withArray("files").add(duplicate.at("/package/files/0").deepCopy());assertThrows(SchemaRejection.class,()->schema.validateRequest(duplicate));var bytes=request("PROMPT");bytes.withObject("package").put("system_instructions","医".repeat(90000));assertThrows(SchemaRejection.class,()->schema.validateRequest(bytes));}
 @Test void strictWireRejectsDuplicateTrailingOversizeAndBlankPrompt()throws Exception{String wire=schema.canonical(request("PROMPT"));assertThrows(Exception.class,()->schema.request((wire+" {}").getBytes(StandardCharsets.UTF_8)));assertThrows(Exception.class,()->schema.request(wire.replace("\"kind\":\"PROMPT\"","\"kind\":\"PROMPT\",\"kind\":\"ROLE\"").getBytes(StandardCharsets.UTF_8)));assertThrows(SchemaRejection.class,()->schema.request(new byte[TaskProfessionalPackageAuthoringSchema.MAXIMUM_REQUEST_BYTES+1]));var blank=request("PROMPT");blank.withObject("package").put("system_instructions"," \t\n");assertThrows(SchemaRejection.class,()->schema.validateRequest(blank));}
 @Test void contentSourceIdentityCannotRepeatWithDifferentHash(){var p=request("PROMPT");p.withArray("content_sources").add(json.tree(new PermissionProtocol.Basis(id(9),H))).add(json.tree(new PermissionProtocol.Basis(id(9),"b".repeat(64))));assertThrows(SchemaRejection.class,()->schema.validateRequest(p));}
 @Test void fixedResponseDoesNotRepresentProductionEligibility()throws Exception{var n=json.object().put("schema_version","1.0.0").put("state","NOT_FOUND").put("production_eligible",false).put("tenant_id",id(1)).put("project_id",id(2)).put("created_by",id(3)).put("operation_name","TASK-PROFESSIONAL-PACKAGE");for(String f:List.of("operation_id","kind","artifact","schema","object_version","target_id","original_key_sha256","request_body_sha256","request_sha256"))n.putNull(f);schema.validate("Status",n);n.put("production_eligible",true);assertThrows(SchemaRejection.class,()->schema.validate("Status",n));}
}
